package com.txanalyzer;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.graphics.*;import android.hardware.display.DisplayManager;import android.hardware.display.VirtualDisplay;import android.media.Image;import android.media.ImageReader;import android.media.projection.*;import android.os.*;import android.view.*;import android.widget.*;import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.text.TextRecognition;import com.google.mlkit.vision.text.latin.TextRecognizerOptions;import java.nio.ByteBuffer;import java.util.*;import java.util.regex.*;
public class CaptureService extends Service {
 MediaProjection projection;VirtualDisplay display;ImageReader reader;WindowManager wm;View overlay;TextView info;Handler handler=new Handler(Looper.getMainLooper());boolean busy=false;String lastSession="";ArrayDeque<String> history=new ArrayDeque<>();long lastRead=0;
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent intent,int flags,int id){if(intent==null)return START_NOT_STICKY;NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("capture","Đang phân tích màn hình",NotificationManager.IMPORTANCE_LOW));Notification n=new Notification.Builder(this,"capture").setContentTitle("TX MD5 Analyzer đang chạy").setContentText("Chạm Dừng trong ứng dụng để ngắt chia sẻ màn hình").setSmallIcon(android.R.drawable.ic_menu_view).build();if(Build.VERSION.SDK_INT>=29)startForeground(1,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION);else startForeground(1,n);showOverlay();try{MediaProjectionManager mgr=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);Intent data=(Intent)intent.getParcelableExtra("data");projection=mgr.getMediaProjection(intent.getIntExtra("result",-1),data);projection.registerCallback(new MediaProjection.Callback(){public void onStop(){stopSelf();}},handler);WindowManager windows=(WindowManager)getSystemService(WINDOW_SERVICE);android.util.DisplayMetrics m=new android.util.DisplayMetrics();windows.getDefaultDisplay().getRealMetrics(m);int w=m.widthPixels,h=m.heightPixels;reader=ImageReader.newInstance(w,h,PixelFormat.RGBA_8888,2);reader.setOnImageAvailableListener(r->process(r),handler);display=projection.createVirtualDisplay("TX Analyzer",w,h,m.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,handler);}catch(Exception e){if(info!=null)info.setText("Lỗi ghi màn hình: "+e.getMessage());stopSelf();}return START_NOT_STICKY;}
 void showOverlay(){wm=(WindowManager)getSystemService(WINDOW_SERVICE);LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(18,12,18,12);panel.setBackgroundColor(Color.argb(235,20,30,52));TextView header=new TextView(this);header.setText("TX MD5 • THỐNG KÊ  ✕");header.setTextColor(Color.WHITE);header.setTextSize(16);panel.addView(header);info=new TextView(this);info.setText("Đang chờ nhận diện...\nKết quả chỉ mang tính thống kê");info.setTextColor(Color.WHITE);info.setTextSize(14);panel.addView(info);WindowManager.LayoutParams p=new WindowManager.LayoutParams(520,-2,Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.LEFT;p.x=30;p.y=160;header.setOnTouchListener(new View.OnTouchListener(){float sx,sy;int ox,oy;public boolean onTouch(View v,android.view.MotionEvent e){if(e.getAction()==0){sx=e.getRawX();sy=e.getRawY();ox=p.x;oy=p.y;return true;}if(e.getAction()==1){if(Math.abs(e.getRawX()-sx)<12&&Math.abs(e.getRawY()-sy)<12){stopSelf();return true;}return true;}if(e.getAction()==2){p.x=ox+(int)(e.getRawX()-sx);p.y=oy+(int)(e.getRawY()-sy);wm.updateViewLayout(panel,p);return true;}return false;}});overlay=panel;wm.addView(overlay,p);}
 void process(ImageReader r){Image image=r.acquireLatestImage();if(image==null)return;if(busy||System.currentTimeMillis()-lastRead<2500){image.close();return;}lastRead=System.currentTimeMillis();busy=true;try{Image.Plane plane=image.getPlanes()[0];ByteBuffer buffer=plane.getBuffer();int stride=plane.getRowStride(),pixel=plane.getPixelStride();Bitmap padded=Bitmap.createBitmap(image.getWidth()+(stride-image.getWidth()*pixel)/pixel,image.getHeight(),Bitmap.Config.ARGB_8888);padded.copyPixelsFromBuffer(buffer);Bitmap bitmap=Bitmap.createBitmap(padded,0,0,image.getWidth(),image.getHeight());padded.recycle();image.close();TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS).process(InputImage.fromBitmap(bitmap,0)).addOnSuccessListener(t->{parse(t.getText());bitmap.recycle();busy=false;}).addOnFailureListener(e->{bitmap.recycle();busy=false;});}catch(Exception e){image.close();busy=false;}}
 void parse(String s){String normalized=s.toUpperCase(Locale.ROOT);Matcher session=Pattern.compile("#\\s*(\\d{4,10})").matcher(normalized);String id=session.find()?session.group(1):"Không rõ";Matcher result=Pattern.compile("(?<!\\d)(\\d{1,2})(?!\\d)").matcher(normalized);String number="Chưa xác định";while(result.find()){int v=Integer.parseInt(result.group(1));if(v>=3&&v<=18){number=""+v;break;}}if(!id.equals("Không rõ")&&!id.equals(lastSession)){lastSession=id;if(!number.equals("Chưa xác định")){history.addLast(number);if(history.size()>30)history.removeFirst();}}int high=0,low=0;for(String v:history){int n=Integer.parseInt(v);if(n>=11)high++;else low++;}final String text="Phiên: "+id+"\nSố OCR: "+number+" (cần xác minh)\nMẫu ghi nhận: "+history.size()+"\nTài (11–18): "+high+" | Xỉu (3–10): "+low+"\nKhông thể suy ra MD5 từ ảnh\nKhông phải tín hiệu đặt cược";handler.post(()->{if(info!=null)info.setText(text);});}
 public void onDestroy(){if(display!=null)display.release();if(reader!=null)reader.close();if(projection!=null)projection.stop();if(wm!=null&&overlay!=null)wm.removeView(overlay);super.onDestroy();}
}
